// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/adapters/status.ts`. Edit the source and run `just generate`.
// `dotclaude-spec status [<id>]` and `dotclaude-spec next [<id>]`: the lanes of a change.

import { LANES, type Lane } from "../../../kernel/spec-store.ts";
import { readBriefs, readEntries } from "./plan-files.ts";
import { type Run, resolveId } from "./run.ts";

/** The icon of each lane. */
export const ICONS: Readonly<Record<Lane, string>> = {
  planned: "○",
  doing: "●",
  review: "◐",
  done: "✓",
  blocked: "✗",
};

/** Prints the counts and the lane of each package of the change. */
export const statusCommand = async (
  run: Run,
  args: string[],
): Promise<number> => {
  const id = await resolveId(run, args[0]);
  if (id === null) return 1;
  const state = await run.store.state(id);
  if (state === null) {
    run.io.error(`The change \`${id}\` has no \`state.json\`.`);
    return 1;
  }
  const packages = Object.entries(await run.store.lanes(id, state));
  const count = (lane: Lane): number =>
    packages.filter(([, l]) => l === lane).length;
  run.io.log(`◆ ${id} ${count("done")}/${packages.length}`);
  run.io.log(LANES.map((lane) => `${ICONS[lane]} ${count(lane)}`).join("  "));
  for (const [name, lane] of packages) {
    run.io.log(`${ICONS[lane]} ${name} ${lane}`);
  }
  return 0;
};

/**
 * Prints the brief of the next package: the first in the order of `packages.md`
 * that is `planned` or `doing`, that has a brief, and whose deps are all `done`.
 */
export const nextCommand = async (
  run: Run,
  args: string[],
): Promise<number> => {
  const id = await resolveId(run, args[0]);
  if (id === null) return 1;
  const state = await run.store.state(id);
  if (state === null) {
    run.io.error(`The change \`${id}\` has no \`state.json\`.`);
    return 1;
  }
  const lanes = await run.store.lanes(id, state);
  const { packages, texts } = await readBriefs(run.store, id);
  const order = (await readEntries(run.store, id)).map((e) => e.id);
  const rank = (pkg: string): number => {
    const i = order.indexOf(pkg);
    return i < 0 ? order.length : i;
  };
  const ready = packages
    .filter((p) => ["planned", "doing"].includes(lanes[p.front.id] ?? ""))
    .filter((p) => p.front.deps.every((d) => lanes[d] === "done"))
    .sort((a, b) => rank(a.front.id) - rank(b.front.id));
  const next = ready[0];
  if (!next) {
    run.io.log(`No package of \`${id}\` is ready.`);
    return 0;
  }
  run.io.log((texts[next.front.id] ?? "").trimEnd());
  return 0;
};
